-- StartupGo's database: 3 tables (entities, facts, assessments) and read-only views named like the older tables.
-- Generated by Modules/DataAPIs/unify.py --sql from DB/schema.sql and the runtime DB's reference tables; do not edit.
-- Writers (Backend, Agent) write the 3 tables; the views are for reading.

-- One row per real-world thing. Startup entities keep the startup's id; others get ids from 100000.
CREATE TABLE IF NOT EXISTS entities (
    id             INTEGER PRIMARY KEY,
    key            TEXT NOT NULL UNIQUE,        -- stable identity, e.g. startup:notpla, investor:lowercarbon-capital
    kind           TEXT NOT NULL CHECK (kind IN ('startup','candidate','investor','person','organisation','funding_call')),
    slug           TEXT,
    name           TEXT NOT NULL,
    website        TEXT,
    domain         TEXT,                        -- dedupe key (the Agent's website_domain)
    country        TEXT,
    city           TEXT,
    sector         TEXT,                        -- startups: curated sector; candidates: BlueInvest sector
    blue_sector    TEXT,                        -- Agent vocabulary (vocab.BLUE_SECTORS)
    tagline        TEXT,
    description    TEXT,
    founded_year   INTEGER,
    stage          TEXT,
    pipeline_stage TEXT,
    company_number TEXT,                        -- UK Companies House
    lei            TEXT,
    vat            TEXT,
    cordis_id      TEXT,
    blueinvest_id  TEXT,
    pdl_id         TEXT,
    sec_cik        TEXT,
    created_at     TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at     TEXT NOT NULL DEFAULT (datetime('now'))
);

-- One row per piece of evidence, in the Agent's fact format (startup_agent/facts.py) plus provenance.
CREATE TABLE IF NOT EXISTS facts (
    id                INTEGER PRIMARY KEY,
    entity_id         INTEGER NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    section           TEXT NOT NULL,            -- Agent schema section A-J; Api = StartupGo extension (API sources, analyst entries)
    field             TEXT NOT NULL,            -- Agent field (dev_stage, founders, grants, ...) or extension field
    value             TEXT,                     -- JSON: scalar, list or object (e.g. a round or a pilot)
    related_entity_id INTEGER REFERENCES entities(id) ON DELETE SET NULL,  -- investor in a round, founder, ...
    evidence          TEXT,                     -- verbatim quote or filing/registry text
    source_url        TEXT,
    source_type       TEXT NOT NULL,            -- registry | grant_db | eu_projects | patent | news | website | pitch_deck | manual
    source_name       TEXT NOT NULL,            -- which API, table or the Agent produced it
    status            TEXT NOT NULL CHECK (status IN ('verified','claimed','inferred')),
    confidence        REAL NOT NULL,
    retrieved_at      TEXT,
    observed_on       TEXT,                     -- when the fact was true
    is_current        INTEGER NOT NULL DEFAULT 1
);

-- One row per scoring run per entity (Stage 2 output), kept over time.
CREATE TABLE IF NOT EXISTS assessments (
    id                 INTEGER PRIMARY KEY,
    entity_id          INTEGER NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    assessed_at        TEXT NOT NULL,
    engine             TEXT NOT NULL,           -- seed-estimate | analyst | startupgo-pipeline | agent
    assessor           TEXT,
    confidence         TEXT,                    -- low | medium | high (analyst assessments)
    trl INTEGER, brl INTEGER, crl INTEGER, iprl INTEGER, tmrl INTEGER, frl INTEGER,  -- 1-9
    oir INTEGER,                                -- Ocean Impact Readiness 1-5
    levels_basis       TEXT,                    -- JSON: facts and rules behind each level
    navigator_kpis     TEXT,                    -- JSON: {"B2": {"level": 2, "claim": "...", "source_url": "..."}}
    criteria           TEXT,                    -- JSON: 10 investment criteria, score 1-5 + confidence
    investment_score   REAL,
    overall_confidence REAL,
    red_flags          TEXT,                    -- JSON list
    data_gaps          TEXT,                    -- JSON list
    next_steps         TEXT,                    -- JSON list
    peers              TEXT,                    -- JSON list
    features           TEXT,                    -- JSON: StartupGo features {name: {value, text, evidence}}
    rationale          TEXT,
    judge_status       TEXT,
    UNIQUE (entity_id, engine, assessed_at)
);

CREATE INDEX IF NOT EXISTS idx_entities_kind ON entities(kind);
CREATE INDEX IF NOT EXISTS idx_entities_domain ON entities(domain);
CREATE INDEX IF NOT EXISTS idx_facts_entity ON facts(entity_id, section, field);
CREATE INDEX IF NOT EXISTS idx_assessments_entity ON assessments(entity_id, engine, assessed_at);

-- Retrieval log: what the Agent looked at on each research run (Modules/Agent retrievals.py). One run per
-- candidate researched; every page loaded and web search made is one retrieval, in order.
-- Facts cite their retrieval through facts.source_url = agent_retrievals.url.
CREATE TABLE IF NOT EXISTS agent_runs (
    id          INTEGER PRIMARY KEY,
    entity_id   INTEGER REFERENCES entities(id) ON DELETE SET NULL,  -- NULL until the startup exists
    name        TEXT NOT NULL,
    website     TEXT NOT NULL,
    status      TEXT NOT NULL CHECK (status IN ('ok','error')),
    started_at  TEXT NOT NULL,
    finished_at TEXT NOT NULL,
    entry_id    TEXT,                       -- Modules/Agent output/startups/<entry_id>.json produced by this run
    error       TEXT
);

CREATE TABLE IF NOT EXISTS agent_retrievals (
    id           INTEGER PRIMARY KEY,
    run_id       INTEGER NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    seq          INTEGER NOT NULL,          -- order within the run
    kind         TEXT NOT NULL CHECK (kind IN ('page','search')),
    url          TEXT,                      -- page URL
    query        TEXT,                      -- search query, for kind = 'search'
    provider     TEXT,                      -- search provider (gemini | brave)
    source_type  TEXT,                      -- website | pitch_deck | news | registry | ... (Agent source types)
    status       TEXT NOT NULL CHECK (status IN ('ok','error','skipped','cached')),
    detail       TEXT,                      -- error message, skip reason, or JSON list of search hits
    used         INTEGER NOT NULL DEFAULT 0, -- 1 when a stored fact cites this URL
    retrieved_at TEXT NOT NULL,
    UNIQUE (run_id, seq)
);

CREATE INDEX IF NOT EXISTS idx_agent_runs_entity ON agent_runs(entity_id, started_at);
CREATE INDEX IF NOT EXISTS idx_agent_retr_run    ON agent_retrievals(run_id, seq);
CREATE INDEX IF NOT EXISTS idx_agent_retr_url    ON agent_retrievals(url);

-- Every startup entity, scored or not: the Backend lists these; `startups` below keeps only fully assessed ones.
DROP VIEW IF EXISTS all_startups;
CREATE VIEW all_startups AS SELECT e.id, e.slug, e.name, e.tagline, e.description, e.sector, e.country, e.city, e.founded_year, e.website,
                           e.stage, e.pipeline_stage, e.created_at, e.updated_at
                    FROM entities e WHERE e.kind='startup';

DROP VIEW IF EXISTS startups;
CREATE VIEW startups AS SELECT e.id, e.slug, e.name, e.tagline, e.description, e.sector, e.country, e.city, e.founded_year, e.website,
                           e.stage, e.pipeline_stage, e.created_at, e.updated_at
                    FROM entities e WHERE e.kind='startup' AND EXISTS (SELECT 1 FROM assessments a WHERE a.entity_id=e.id AND crl IS NOT NULL AND trl IS NOT NULL AND brl IS NOT NULL AND iprl IS NOT NULL AND tmrl IS NOT NULL AND frl IS NOT NULL);

DROP VIEW IF EXISTS readiness_assessments;
CREATE VIEW readiness_assessments AS SELECT id, entity_id AS startup_id, assessed_at AS assessed_on, COALESCE(assessor, engine) AS assessor,
                                        COALESCE(confidence, 'low') AS confidence, crl, trl, brl, iprl, tmrl, frl, rationale
                                 FROM assessments WHERE crl IS NOT NULL AND trl IS NOT NULL AND brl IS NOT NULL AND iprl IS NOT NULL AND tmrl IS NOT NULL AND frl IS NOT NULL;

DROP VIEW IF EXISTS startup_ocean_kpis;
CREATE VIEW startup_ocean_kpis AS SELECT entity_id AS startup_id, json_extract(value,'$.kpi') AS kpi_code, json_extract(value,'$.level') AS evidence_level,
                                    json_extract(value,'$.claim') AS claim, source_url FROM facts WHERE field='navigator_kpi' AND is_current=1;

DROP VIEW IF EXISTS funding_rounds;
CREATE VIEW funding_rounds AS SELECT id, entity_id AS startup_id, json_extract(value,'$.round_type') AS round_type, json_extract(value,'$.amount') AS amount,
                                json_extract(value,'$.currency') AS currency, json_extract(value,'$.announced_on') AS announced_on,
                                json_extract(value,'$.lead_investors') AS lead_investors, json_extract(value,'$.notes') AS notes, source_url
                         FROM facts WHERE source_name IN ('funding_rounds','analyst','agent') AND field IN ('equity_rounds','grants') AND is_current=1;

DROP VIEW IF EXISTS sources;
CREATE VIEW sources AS SELECT id, entity_id AS startup_id, json_extract(value,'$.title') AS title, source_url AS url FROM facts WHERE field='reference';

DROP VIEW IF EXISTS notes;
CREATE VIEW notes AS SELECT id, entity_id AS startup_id, json_extract(value,'$.author') AS author, json_extract(value,'$.body') AS body,
                       json_extract(value,'$.created_at') AS created_at FROM facts WHERE field='analyst_note';

DROP VIEW IF EXISTS readiness_dimensions;
CREATE VIEW readiness_dimensions(code, name, description, sort_order) AS VALUES ('CRL', 'Customer', 'Customer readiness: from a hunch about a need to scalable, repeatable sales.', 1), ('TRL', 'Technology', 'Technology readiness: from a research idea to a solution proven in actual operations.', 2), ('BRL', 'Business model', 'Business readiness: from a vague idea to a proven, sustainable (economic + environmental + social) business model.', 3), ('IPRL', 'IP', 'IPR readiness: from hypothesised IP to a proven IP strategy with key rights granted.', 4), ('TMRL', 'Team', 'Team readiness: from a single founder to a high-performing organisation.', 5), ('FRL', 'Funding', 'Funding readiness: from no funding insight to secured runway and full financial control.', 6);

DROP VIEW IF EXISTS readiness_levels;
CREATE VIEW readiness_levels(dimension_code, level, summary) AS VALUES ('CRL', 1, 'A possible need is assumed; no clear customer hypotheses.'), ('CRL', 2, 'Secondary market research; first problem/need hypothesis.'), ('CRL', 3, 'Primary feedback from a few users or experts; hypothesis updated.'), ('CRL', 4, 'Problem confirmed by multiple customers; segments and buyer roles identified.'), ('CRL', 5, 'Customers confirm the product can solve their problem (problem-solution fit).'), ('CRL', 6, 'Customer testing confirms value; structured sales activities started.'), ('CRL', 7, 'Customer agreements in place; first or test sales; small active user base.'), ('CRL', 8, 'Market-ready product sold near target price; initial traction; sales process staffed.'), ('CRL', 9, 'Widespread, repeatable, scalable sales; significant traction.'), ('TRL', 1, 'Research results with potential applications; vague technology idea.'), ('TRL', 2, 'Technology concept defined; applications speculative.'), ('TRL', 3, 'Lab tests show the concept could work; active R&D started.'), ('TRL', 4, 'Components integrated and working together in the lab (initial validation).'), ('TRL', 5, 'Components validated in a relevant (simulated) environment.'), ('TRL', 6, 'Representative prototype demonstrated in a relevant environment.'), ('TRL', 7, 'Near-complete prototype works in an operational environment.'), ('TRL', 8, 'Complete technology proven in actual operations by first users.'), ('TRL', 9, 'Scalable technology proven in operations by several users over time.'), ('BRL', 1, 'Vague business idea; little market or competition insight.'), ('BRL', 2, 'Business concept and value proposition described; brief market familiarity.'), ('BRL', 3, 'Proposed business model (e.g. canvas), TAM/SAM estimates, competition defined.'), ('BRL', 4, 'Simplified P&L indicates viability; initial sustainability assessment (own assumptions).'), ('BRL', 5, 'Revenue and cost sides validated with external feedback; P&L updated.'), ('BRL', 6, 'Complete sustainable business model tested in realistic scenarios (pilot, pre-order).'), ('BRL', 7, 'First commercial revenue shows willingness to pay; key partner agreements in place.'), ('BRL', 8, '1-3 years of operations show the sustainable model holds; channels and supply chain live.'), ('BRL', 9, 'Sustainable business model operational and proven profitable and impactful over time.'), ('IPRL', 1, 'Hypothesising that results might contain some form of IP.'), ('IPRL', 2, 'IP forms mapped; ownership clarified.'), ('IPRL', 3, 'Key IP described in detail; initial protectability evaluation.'), ('IPRL', 4, 'Protectability confirmed by professional; priorities decided.'), ('IPRL', 5, 'Draft IP strategy; first formal application of key IP filed.'), ('IPRL', 6, 'Complete IP strategy; positive response from authorities; freedom-to-operate assessed.'), ('IPRL', 7, 'Key IP in national/regional phase in relevant markets.'), ('IPRL', 8, 'IP strategy fully implemented; key IP granted in first market.'), ('IPRL', 9, 'IP strategy proven to create value; key IP granted in several countries.'), ('TMRL', 1, 'Individual lacking key competencies.'), ('TMRL', 2, '1-2 people with limited competencies; first idea of needs.'), ('TMRL', 3, 'Some competencies present; gaps identified with a near-term plan.'), ('TMRL', 4, 'Committed champion; several competencies present; roles being discussed.'), ('TMRL', 5, 'Founding team with main competencies; shareholder agreement signed.'), ('TMRL', 6, 'Complementary, diverse founding team with clear CEO; advisors being recruited.'), ('TMRL', 7, 'Well-functioning team with clear roles; board and advisors operational.'), ('TMRL', 8, 'Experienced leadership team; competent board; HR processes in place.'), ('TMRL', 9, 'High-performing organisation with continuous development.'), ('FRL', 1, 'Little insight into costs or funding options.'), ('FRL', 2, 'Basic plan with funding options for initial milestones.'), ('FRL', 3, 'Funding secured for initial feasibility work (1-6 months).'), ('FRL', 4, 'Verification plan in place and substantially funded.'), ('FRL', 5, 'Investor pitch tested; 12-month budget; funding strategy decided.'), ('FRL', 6, 'Improved pitch tested; 3-5 year P&L and cash flow.'), ('FRL', 7, 'Discussions with investors around a defined offer; business plan in place.'), ('FRL', 8, 'Term-sheet-level discussions; due-diligence materials ready.'), ('FRL', 9, '6-12+ months runway secured; full financial monitoring.');

DROP VIEW IF EXISTS ocean_impact_areas;
CREATE VIEW ocean_impact_areas(code, name, orientation) AS VALUES ('A', 'Sustainably managed ocean resources', 'Solutions to over-exploitation'), ('B', 'A clean ocean', 'Solutions for pollution'), ('C', 'Thriving and restored marine habitats', 'Solutions to physical damage of marine & coastal habitats'), ('D', 'Towards 1.5C', 'Reducing & sequestering GHG emissions'), ('E', 'Climate-resilient coastal communities', 'Reducing vulnerability & enhancing adaptive capacity'), ('F', 'Positive socio-economic outcomes', 'Well-being & equity');

DROP VIEW IF EXISTS ocean_kpis;
CREATE VIEW ocean_kpis(code, area_code, name, qualitative_only) AS VALUES ('A1', 'A', 'Volume of biomass preserved or restored', 0), ('A2', 'A', 'Volume of seafood waste reduced', 0), ('A3', 'A', 'Welfare of marine life', 1), ('A4', 'A', 'Tonnes of ocean-based seaweed and bivalves produced', 0), ('B1', 'B', 'Volume of primary micro-plastics diverted from nature (or landfill)', 0), ('B2', 'B', 'Volume of macro-plastic diverted from nature (or landfill)', 0), ('B3', 'B', 'Nitrogen/phosphorous pollution mitigated', 0), ('B4', 'B', 'Volume of contaminated waste water from land-based sources diverted from waterways', 0), ('B5', 'B', 'Invasive species reduced or avoided', 1), ('B6', 'B', 'Reduction in other pollution (heavy metals, chemicals, sound, etc.)', 0), ('C1', 'C', 'Area of coral reefs protected or restored', 0), ('C2', 'C', 'Area of mangroves protected or restored', 0), ('C3', 'C', 'Area of seagrasses protected or restored', 0), ('C4', 'C', 'Area of salt marshes protected or restored', 0), ('C5', 'C', 'Area of kelp forest protected or restored', 0), ('C6', 'C', 'Area of other habitat protected or restored', 0), ('D1', 'D', 'GHG emissions reduced or avoided', 0), ('D2', 'D', 'GHG emissions generated', 0), ('D3', 'D', 'Carbon sequestered', 0), ('D4', 'D', 'NOx emissions mitigated', 0), ('D5', 'D', 'SOx emissions mitigated', 0), ('E1', 'E', 'Length of coastline protected', 0), ('E2', 'E', 'Use of ocean information products/services in climate adaptation decisions', 0), ('E3', 'E', 'Number of people supported to adapt to climate change', 0), ('E4', 'E', 'Enhanced food security', 1), ('F1', 'F', 'Number of jobs created', 0), ('F2', 'F', 'People completing education / training programmes', 0), ('F3', 'F', 'Share of employees that are women', 0), ('F4', 'F', 'Entry-level wage vs local minimum wage', 0), ('F5', 'F', 'Particulate emissions mitigated', 0);

DROP VIEW IF EXISTS feature_definitions;
CREATE VIEW feature_definitions(name, feature_group, description, unit, importance, origin, sources) AS VALUES ('total_raised_usd', 'rounds', 'Total capital raised; largest of announced rounds, filings (Form D, priced SH01) and the PDL aggregate. All candidates kept in evidence.', 'USD', 'high', 'paper', 'funding_rounds, sec_form_d, uk_sh01, people_data_labs'), ('round_count', 'rounds', 'Number of distinct funding rounds (allotments within 90 days merged).', 'rounds', 'high', 'paper', 'funding_rounds, uk_sh01, sec_form_d, people_data_labs'), ('last_round_date', 'rounds', 'Date of the most recent round from any source.', 'date', 'high', 'user-list', 'all funding sources'), ('last_round_type', 'rounds', 'Stage of the most recent announced round.', NULL, 'high', 'paper', 'funding_rounds, people_data_labs'), ('months_since_last_round', 'rounds', 'Months from the last round to the as-of date.', 'months', 'high', 'user-list', 'derived'), ('no_round_24m', 'rounds', '1 if no round in the last 730 days: the paper''s ''longtime'' failure rule.', 'flag', 'high', 'paper', 'derived'), ('median_months_between_rounds', 'rounds', 'Median gap between consecutive rounds (funding speed).', 'months', 'high', 'user-list', 'derived'), ('funding_velocity_usd_per_year', 'rounds', 'Total raised divided by company age.', 'USD/yr', 'medium', 'recommended', 'derived'), ('latest_price_per_share', 'rounds', 'Price paid per share in the latest priced allotment (UK SH01).', 'currency/share', 'medium', 'user-list', 'uk_sh01'), ('implied_post_money', 'rounds', 'Latest priced allotment price x total shares after it (UK SH01).', 'currency', 'high', 'user-list', 'uk_sh01'), ('valuation_step_up', 'rounds', 'Latest priced share price / previous priced round''s price.', 'x', 'high', 'recommended', 'uk_sh01'), ('investor_count', 'investors', 'Number of investors: Form D count if filed, else distinct investors known.', 'investors', 'medium', 'paper', 'sec_form_d, funding_rounds'), ('lead_investors', 'investors', 'Lead investors across rounds.', NULL, 'high', 'user-list', 'funding_rounds'), ('investor_quality_max', 'investors', 'Best investor tier score (analyst-curated, investor_tiers.json).', '0-1', 'high', 'paper', 'investor_tiers.json'), ('investor_quality_mean', 'investors', 'Mean tier score across all known investors.', '0-1', 'medium', 'paper', 'investor_tiers.json'), ('specialist_investor_share', 'investors', 'Share of investors that are ocean or climate specialists.', '0-1', 'medium', 'recommended', 'investor_tiers.json'), ('follow_on_investors', 'investors', 'Investors appearing in more than one round of this startup.', 'investors', 'medium', 'recommended', 'funding_rounds'), ('founder_count', 'founders', 'Founders: directors appointed within 30 days of incorporation (UK), else beneficial owners.', 'people', 'medium', 'paper', 'uk_companies_house'), ('serial_founder_count', 'founders', 'Founders who directed another company before this one was incorporated.', 'people', 'medium', 'paper', 'uk_companies_house_officer'), ('prior_ventures_total', 'founders', 'Companies the founders directed before this one.', 'companies', 'medium', 'paper', 'uk_companies_house_officer'), ('prior_ventures_failed', 'founders', 'Of those, how many are dissolved, liquidated or in administration.', 'companies', 'medium', 'recommended', 'uk_companies_house_officer'), ('founder_retention', 'founders', 'Share of founders still serving as directors.', '0-1', 'high', 'recommended', 'uk_companies_house'), ('officer_churn', 'founders', 'Resigned officers / all officers ever appointed.', '0-1', 'medium', 'recommended', 'uk_companies_house'), ('category_tags', 'category', 'Tags used for peer similarity: sector, industry, YC tags, SIC codes, ocean impact areas, keywords.', 'JSON', 'medium', 'paper', 'seed, people_data_labs, yc_oss, uk_companies_house, startup_ocean_kpis'), ('top_peer', 'category', 'Most similar startup in the DB by weighted tag overlap.', NULL, 'medium', 'user-list', 'derived'), ('headcount', 'momentum', 'Latest employee count.', 'employees', 'high', 'user-list', 'people_data_labs, yc_oss'), ('open_roles', 'momentum', 'Open job postings matched to the company.', 'jobs', 'medium', 'recommended', 'serpapi_google_jobs'), ('news_mentions_12m', 'momentum', 'News items naming the company in the last 12 months.', 'items', 'low', 'recommended', 'google_news_rss, gdelt_doc'), ('allotments_last_12m', 'momentum', 'UK share allotments in the last 12 months (raise cadence; often precedes announcements).', 'filings', 'medium', 'recommended', 'uk_sh01'), ('patent_count', 'momentum', 'Patents assigned to the company.', 'patents', 'medium', 'user-list', 'google patents / serpapi'), ('patents_granted', 'momentum', 'Of those, how many are granted.', 'patents', 'medium', 'recommended', 'google patents / serpapi'), ('grant_share', 'rounds', 'Share of announced funding that is non-dilutive (grants).', '0-1', 'medium', 'recommended', 'funding_rounds'), ('company_age_years', 'category', 'Years since founding (curated year, else earliest registry date).', 'years', 'low', 'user-list', 'startups, uk_companies_house'), ('distress_flag', 'risk', '1 if insolvency case, administration/liquidation status, or no active officers.', 'flag', 'high', 'recommended', 'uk_companies_house'), ('registry_status', 'risk', 'Registered company status.', NULL, 'high', 'recommended', 'uk_companies_house, gleif_lei'), ('funding_total_spread', 'integrity', 'Max/min ratio between independent total-raised figures (1 = sources agree).', 'x', 'medium', 'recommended', 'derived'), ('founded_year_conflicts', 'integrity', 'Distinct founded-year values across sources, including the curated one.', 'values', 'low', 'recommended', 'field_suggestions'), ('down_round_flag', 'rounds', '1 if any priced round was below the previous round''s price (UK SH01).', 'flag', 'high', 'recommended', 'uk_sh01'), ('founder_other_ventures', 'founders', 'All other companies the founders direct or directed, any date (side projects, spin-outs, next venture).', 'companies', 'low', 'recommended', 'uk_companies_house_officer'), ('eu_grants_total_eur', 'grants', 'EU research/innovation funding received (sum of the company''s own EU contribution, CORDIS).', 'EUR', 'high', 'recommended', 'cordis_projects'), ('eu_projects_count', 'grants', 'EU-funded projects the company takes part in (any role).', 'projects', 'medium', 'recommended', 'cordis_projects'), ('eu_projects_funded', 'grants', 'Of those, projects where the company itself receives EU money.', 'projects', 'medium', 'recommended', 'cordis_projects'), ('eu_coordinator_count', 'grants', 'EU projects the company coordinates (leadership signal).', 'projects', 'high', 'recommended', 'cordis_projects'), ('eu_first_grant_year', 'grants', 'Start year of the company''s first EU project.', 'year', 'low', 'recommended', 'cordis_projects'), ('eu_active_projects', 'grants', 'EU projects currently running (signed, end date in the future).', 'projects', 'medium', 'recommended', 'cordis_projects'), ('eic_or_sme_instrument', 'grants', '1 if funded by the EIC or the H2020 SME Instrument: highly selective startup programmes.', 'flag', 'high', 'recommended', 'cordis_projects'), ('mission_ocean_grant', 'grants', '1 if part of the EU Mission ''Restore our Ocean and Waters''.', 'flag', 'medium', 'recommended', 'cordis_projects'), ('eu_consortium_links', 'grants', 'Total consortium partners across the company''s EU projects (network reach; partners in several projects count each time).', 'links', 'medium', 'recommended', 'cordis_projects'), ('cordis_sme_confirmed', 'grants', '1 if CORDIS records the company as an SME.', 'flag', 'low', 'recommended', 'cordis_projects'), ('grant_to_equity_ratio', 'grants', 'EU grants / total raised: grant dependency, typical for ocean deep tech.', 'ratio', 'medium', 'recommended', 'derived'), ('ocean_patent_count', 'ocean', 'Patents with at least one ocean-technology CPC class (aquaculture, seaweed, algae products, ocean energy, vessels, ship emissions, cleanup, ocean sensing).', 'patents', 'medium', 'recommended', 'google_patents_page'), ('ocean_patent_share', 'ocean', 'Ocean-class patents / patents with known classes. Misses marine-use patents filed in generic classes.', '0-1', 'low', 'recommended', 'google_patents_page'), ('ocean_tech_groups', 'ocean', 'Ocean technology groups found in the company''s patent classes.', 'JSON', 'low', 'recommended', 'google_patents_page'), ('blueinvest_listed', 'ocean', '1 if the company is in the EU BlueInvest Project Pipeline (investor-facing showcase); 0 if not found.', 'flag', 'medium', 'recommended', 'blueinvest_pipeline'), ('blueinvest_trl', 'ocean', 'Self-reported TRL on the BlueInvest profile.', '1-9', 'high', 'recommended', 'blueinvest_profile'), ('blueinvest_funding_sought_eur', 'ocean', 'Funding sought according to the BlueInvest profile (largest EUR amount in its financial needs text).', 'EUR', 'medium', 'recommended', 'blueinvest_profile'), ('blueinvest_sector', 'ocean', 'BlueInvest blue-economy sector.', NULL, 'medium', 'recommended', 'blueinvest_profile'), ('trl_gap', 'integrity', 'Self-reported TRL (BlueInvest) minus the seed TRL estimate; large gaps need checking.', 'levels', 'medium', 'recommended', 'blueinvest_profile, readiness_assessments'), ('board_size', 'founders', 'Current directors / board members (Companies House directors, SEC Form D directors, PDL board titles).', 'people', 'medium', 'recommended', 'uk_companies_house, sec_form_d_document, pdl_person_search'), ('technical_open_roles', 'momentum', 'Open engineering / science / R&D roles.', 'jobs', 'medium', 'recommended', 'job_boards, serpapi_google_jobs'), ('commercial_open_roles', 'momentum', 'Open sales / business development / marketing / customer roles.', 'jobs', 'medium', 'recommended', 'job_boards, serpapi_google_jobs'), ('blueinvest_peer_count', 'category', 'Similar companies in the EU BlueInvest pipeline (similarity >= 0.1): competitor density.', 'companies', 'medium', 'recommended', 'blueinvest_pipeline'), ('peer_median_trl', 'category', 'Median TRL of the 10 most similar BlueInvest companies.', '1-9', 'medium', 'recommended', 'blueinvest_pipeline'), ('trl_vs_peers', 'category', 'Own TRL (BlueInvest if listed, else seed estimate) minus the peer median TRL.', 'levels', 'medium', 'recommended', 'blueinvest_pipeline, readiness_assessments'), ('first_patent_granted', 'momentum', 'Was the company''s first utility patent application granted? 1 granted, 0 abandoned/refused; ''pending'' while undecided; ''unknown'' for international (WO) filings, which never grant themselves (needs family data). Patent ''lottery'' paper: first-patent approval predicts later funding and growth.', 'flag', 'medium', 'user-list', 'google patents'), ('first_patent_months_to_grant', 'momentum', 'Months from filing to grant for the first utility patent. Mostly reflects the patent office (EPO ~5 years, USPTO less): compare within one office.', 'months', 'low', 'user-list', 'google patents'), ('patents_pending', 'momentum', 'Patent applications still pending.', 'patents', 'low', 'recommended', 'google patents'), ('patents_abandoned', 'momentum', 'Applications abandoned, withdrawn, refused or lapsed for non-payment (WO ''ceased'' excluded: it only ends the international phase).', 'patents', 'medium', 'recommended', 'google patents');
